-- IAMS Phase 1: tenant access helpers, operational tables and least-privilege RLS.
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
create or replace function private.current_company_id() returns uuid language sql stable security definer set search_path=''
as $$ select company_id from public.user_profiles where id=(select auth.uid()) and active=true limit 1 $$;
create or replace function private.current_role() returns text language sql stable security definer set search_path=''
as $$ select role::text from public.user_profiles where id=(select auth.uid()) and active=true limit 1 $$;
create or replace function private.current_employee_id() returns uuid language sql stable security definer set search_path=''
as $$ select employee_id from public.user_profiles where id=(select auth.uid()) and active=true limit 1 $$;
revoke all on function private.current_company_id() from public,anon;
revoke all on function private.current_role() from public,anon;
revoke all on function private.current_employee_id() from public,anon;
grant execute on function private.current_company_id() to authenticated;
grant execute on function private.current_role() to authenticated;
grant execute on function private.current_employee_id() to authenticated;

create table if not exists public.production_units(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),plant_id uuid not null references public.plants(id),department_id uuid references public.departments(id),name text not null,code text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(company_id,code));
create table if not exists public.attendance_policies(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),name text not null,grace_minutes integer not null default 0 check(grace_minutes between 0 and 240),half_day_below_minutes integer not null default 240 check(half_day_below_minutes between 0 and 1440),full_day_minutes integer not null default 480 check(full_day_minutes between 0 and 1440),overtime_after_minutes integer not null default 0 check(overtime_after_minutes between 0 and 1440),break_minutes integer not null default 0 check(break_minutes between 0 and 600),effective_from date not null default current_date,effective_to date,active boolean not null default true,created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),unique(company_id,name,effective_from));
create table if not exists public.holidays(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),plant_id uuid references public.plants(id),holiday_date date not null,name text not null,paid boolean not null default true,created_at timestamptz not null default now(),unique(company_id,plant_id,holiday_date));
create table if not exists public.contractors(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),name text not null,code text not null,contact_name text,contact_phone text,active boolean not null default true,valid_from date,valid_to date,created_at timestamptz not null default now(),unique(company_id,code),check(valid_to is null or valid_from is null or valid_to>=valid_from));
create table if not exists public.contract_workers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),contractor_id uuid not null references public.contractors(id),plant_id uuid references public.plants(id),department_id uuid references public.departments(id),worker_code text not null,full_name text not null,valid_from date not null,valid_to date,active boolean not null default true,created_at timestamptz not null default now(),unique(company_id,worker_code),check(valid_to is null or valid_to>=valid_from));
create table if not exists public.visitors(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),plant_id uuid references public.plants(id),visitor_name text not null,organization text,purpose text not null,host_employee_id uuid references public.employees(id),entry_at timestamptz not null default now(),exit_at timestamptz,authorization_status text not null default 'approved' check(authorization_status in('pending','approved','denied')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(exit_at is null or exit_at>=entry_at));
create table if not exists public.attendance_devices(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),plant_id uuid references public.plants(id),name text not null,device_type text not null check(device_type in('biometric','rfid','csv_import','simulator','other')),external_device_id text,integration_status text not null default 'not_configured' check(integration_status in('not_configured','configured','tested','disabled','error')),last_synced_at timestamptz,active boolean not null default true,config jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(company_id,external_device_id));
create table if not exists public.device_import_jobs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),device_id uuid references public.attendance_devices(id),file_name text not null,status text not null default 'pending' check(status in('pending','validating','ready','completed','failed','cancelled')),total_rows integer not null default 0,accepted_rows integer not null default 0,rejected_rows integer not null default 0,errors jsonb not null default '[]'::jsonb,created_by uuid references auth.users(id),created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,recipient_user_id uuid references auth.users(id) on delete cascade,category text not null,title text not null,body text not null,entity_type text,entity_id text,dedupe_key text,read_at timestamptz,created_at timestamptz not null default now(),unique(company_id,recipient_user_id,dedupe_key));

create index if not exists employees_company_plant_department_idx on public.employees(company_id,plant_id,department_id);
create index if not exists punches_company_employee_time_idx on public.attendance_punches(company_id,employee_id,punched_at desc);
create index if not exists summaries_company_workdate_idx on public.daily_attendance_summaries(company_id,work_date desc);
create index if not exists leave_requests_company_status_dates_idx on public.leave_requests(company_id,status,start_date,end_date);
create index if not exists notifications_recipient_created_idx on public.notifications(recipient_user_id,created_at desc);

do $$ declare r record; begin for r in select schemaname,tablename,policyname from pg_policies where schemaname='public' loop execute format('drop policy if exists %I on %I.%I',r.policyname,r.schemaname,r.tablename); end loop; end $$;
alter table public.production_units enable row level security;
alter table public.attendance_policies enable row level security;
alter table public.holidays enable row level security;
alter table public.contractors enable row level security;
alter table public.contract_workers enable row level security;
alter table public.visitors enable row level security;
alter table public.attendance_devices enable row level security;
alter table public.device_import_jobs enable row level security;
alter table public.notifications enable row level security;

create policy companies_read_tenant on public.companies for select to authenticated using(id=(select private.current_company_id()));
create policy companies_manage_admin on public.companies for update to authenticated using(id=(select private.current_company_id()) and (select private.current_role())='super_admin') with check(id=(select private.current_company_id()) and (select private.current_role())='super_admin');
create policy profiles_read_scoped on public.user_profiles for select to authenticated using(id=(select auth.uid()) or (company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')));
create policy profiles_manage_hr on public.user_profiles for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy plants_read_tenant on public.plants for select to authenticated using(company_id=(select private.current_company_id()));
create policy plants_manage_hr on public.plants for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy departments_read_tenant on public.departments for select to authenticated using(company_id=(select private.current_company_id()));
create policy departments_manage_hr on public.departments for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy employees_read_scoped on public.employees for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager') or id=(select private.current_employee_id()) or supervisor_employee_id=(select private.current_employee_id())));
create policy employees_manage_hr on public.employees for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy shifts_read_tenant on public.shifts for select to authenticated using(company_id=(select private.current_company_id()));
create policy shifts_manage_hr on public.shifts for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy shift_assignments_read_scoped on public.shift_assignments for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy shift_assignments_manage_hr on public.shift_assignments for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy punches_read_scoped on public.attendance_punches for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy punches_insert_authorized on public.attendance_punches for insert to authenticated with check(company_id=(select private.current_company_id()) and (created_by=(select auth.uid()) or (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor')));
create policy summaries_read_scoped on public.daily_attendance_summaries for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy summaries_manage_hr on public.daily_attendance_summaries for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy leave_read_scoped on public.leave_requests for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy leave_insert_self on public.leave_requests for insert to authenticated with check(company_id=(select private.current_company_id()) and employee_id=(select private.current_employee_id()));
create policy leave_review_hr on public.leave_requests for update to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor'));
create policy correction_read_scoped on public.attendance_correction_requests for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy correction_insert_self on public.attendance_correction_requests for insert to authenticated with check(company_id=(select private.current_company_id()) and employee_id=(select private.current_employee_id()));
create policy correction_review_hr on public.attendance_correction_requests for update to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor'));
create policy overtime_read_scoped on public.overtime_requests for select to authenticated using(company_id=(select private.current_company_id()) and ((select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor') or employee_id=(select private.current_employee_id())));
create policy overtime_insert_self on public.overtime_requests for insert to authenticated with check(company_id=(select private.current_company_id()) and employee_id=(select private.current_employee_id()));
create policy overtime_review_hr on public.overtime_requests for update to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor'));
create policy audit_read_hr on public.audit_logs for select to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy production_units_read on public.production_units for select to authenticated using(company_id=(select private.current_company_id()));
create policy production_units_manage on public.production_units for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy attendance_policies_read on public.attendance_policies for select to authenticated using(company_id=(select private.current_company_id()));
create policy attendance_policies_manage on public.attendance_policies for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy holidays_read on public.holidays for select to authenticated using(company_id=(select private.current_company_id()));
create policy holidays_manage on public.holidays for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy contractors_read on public.contractors for select to authenticated using(company_id=(select private.current_company_id()));
create policy contractors_manage on public.contractors for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy contract_workers_read on public.contract_workers for select to authenticated using(company_id=(select private.current_company_id()));
create policy contract_workers_manage on public.contract_workers for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager'));
create policy visitors_read on public.visitors for select to authenticated using(company_id=(select private.current_company_id()));
create policy visitors_manage on public.visitors for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager','plant_manager','department_supervisor'));
create policy devices_read on public.attendance_devices for select to authenticated using(company_id=(select private.current_company_id()));
create policy devices_manage on public.attendance_devices for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy imports_read on public.device_import_jobs for select to authenticated using(company_id=(select private.current_company_id()));
create policy imports_manage on public.device_import_jobs for all to authenticated using(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager')) with check(company_id=(select private.current_company_id()) and (select private.current_role()) in('super_admin','hr_manager'));
create policy notifications_read_self on public.notifications for select to authenticated using(company_id=(select private.current_company_id()) and recipient_user_id=(select auth.uid()));
create policy notifications_update_self on public.notifications for update to authenticated using(company_id=(select private.current_company_id()) and recipient_user_id=(select auth.uid())) with check(company_id=(select private.current_company_id()) and recipient_user_id=(select auth.uid()));

grant select,insert,update,delete on all tables in schema public to authenticated;
grant usage,select on all sequences in schema public to authenticated;
